<?php declare(strict_types=1);
namespace FMonitor2\PilotHttp;
final class MariaDbInstallerDirectoryReader
{
 public function __construct(private readonly \mysqli $db,private readonly string $p,private readonly string $l){}
 public function read(string $day,array $filters=[]):array
 {
  $q=\trim((string)($filters['q']??''));$status=(string)($filters['status']??'');$availability=(string)($filters['availability']??'');$page=\max(1,(int)($filters['page']??1));$limit=50;$offset=($page-1)*$limit;$d=$this->db->real_escape_string($day);$active="EXISTS(SELECT 1 FROM `{$this->p}fm2_order_installers` oi JOIN `{$this->p}fm2_assignment_orders` o ON o.id=oi.assignment_order_id WHERE oi.installer_tab_id=w.installer_tab_id AND o.status='registered' AND o.version_no=(SELECT MAX(x.version_no) FROM `{$this->p}fm2_assignment_orders` x WHERE x.installation_case_id=o.installation_case_id) AND oi.change_action<>'release' AND oi.valid_from<='{$d}' AND (oi.valid_to IS NULL OR oi.valid_to>='{$d}'))";$where="w.reconciliation_state='delivered'";if($q!==''){$needle=$this->db->real_escape_string('%'.$q.'%');$digits=\preg_replace('/\D+/','',$q);$where.=" AND (w.fio LIKE '{$needle}'".($digits!==''?" OR CAST(w.installer_tab_id AS CHAR) LIKE '".$this->db->real_escape_string('%'.\ltrim($digits,'0').'%')."'":'').')';}if($status!=='')$where.=" AND w.employment_status='".$this->db->real_escape_string($status)."'";if($availability==='assigned')$where.=" AND {$active}";elseif($availability==='free')$where.=" AND NOT {$active}";
  try{$summary=$this->db->query("SELECT COUNT(*) total,SUM(w.employment_status='employed') working,SUM({$active}) assigned,MAX(w.workforce_source_updated_at) last_updated FROM `{$this->p}fm2_workforce_catalog` w WHERE w.reconciliation_state='delivered'")->fetch_assoc();$total=(int)$this->db->query("SELECT COUNT(*) n FROM `{$this->p}fm2_workforce_catalog` w WHERE {$where}")->fetch_assoc()['n'];$pages=\max(1,(int)\ceil($total/$limit));if($page>$pages)throw new PilotHttpInfrastructureUnavailable();$catalog=$this->db->query("SELECT w.installer_tab_id,w.fio,w.position,w.employment_status,w.workforce_source_updated_at,w.dismissal_effective_at FROM `{$this->p}fm2_workforce_catalog` w WHERE {$where} ORDER BY w.fio,w.installer_tab_id LIMIT {$limit} OFFSET {$offset}")->fetch_all(MYSQLI_ASSOC);$rows=[];if($catalog!==[]){$ids=\implode(',',\array_map(static fn($r)=>(int)$r['installer_tab_id'],$catalog));$rows=$this->db->query("SELECT oi.installer_tab_id,c.legacy_installation_object_id,l.regnumber,l.ordadr_address FROM `{$this->p}fm2_order_installers` oi JOIN `{$this->p}fm2_assignment_orders` o ON o.id=oi.assignment_order_id JOIN `{$this->p}fm2_installation_cases` c ON c.id=o.installation_case_id JOIN `{$this->l}fm_maintable` l ON l.id=c.legacy_installation_object_id WHERE oi.installer_tab_id IN ({$ids}) AND o.status='registered' AND o.version_no=(SELECT MAX(x.version_no) FROM `{$this->p}fm2_assignment_orders` x WHERE x.installation_case_id=o.installation_case_id) AND oi.change_action<>'release' AND oi.valid_from<='{$d}' AND (oi.valid_to IS NULL OR oi.valid_to>='{$d}') ORDER BY oi.installer_tab_id,oi.valid_from,c.legacy_installation_object_id")->fetch_all(MYSQLI_ASSOC);}}catch(PilotHttpInfrastructureUnavailable $e){throw$e;}catch(\Throwable $e){throw new PilotHttpInfrastructureUnavailable('',0,$e);}
  $by=[];foreach($rows as$r){$tab=self::id($r['installer_tab_id']);$object=self::id($r['legacy_installation_object_id']);if($tab===null||$object===null)throw new PilotHttpInfrastructureUnavailable();$by[$tab][]=['objectId'=>$object,'registrationNumber'=>self::text($r['regnumber']),'address'=>self::text($r['ordadr_address'])];}
  $out=[];$seen=[];foreach($catalog as$r){$tab=self::id($r['installer_tab_id']);$workerStatus=$r['employment_status'];if($tab===null||isset($seen[$tab])||!\in_array($workerStatus,['employed','dismissed'],true))throw new PilotHttpInfrastructureUnavailable();$seen[$tab]=true;$out[]=['tabId'=>$tab,'fullName'=>self::text($r['fio']),'position'=>self::text($r['position']),'status'=>$workerStatus,'updatedAt'=>self::time($r['workforce_source_updated_at']),'dismissalEffectiveAt'=>$r['dismissal_effective_at']===null?null:self::date($r['dismissal_effective_at']),'assignments'=>$by[$tab]??[]];}return['installers'=>$out,'lastUpdatedAt'=>$summary['last_updated']===null?null:self::time($summary['last_updated']),'summary'=>['total'=>(int)$summary['total'],'working'=>(int)$summary['working'],'assigned'=>(int)$summary['assigned']],'total'=>$total,'page'=>$page,'pages'=>$pages,'filters'=>['q'=>$q,'status'=>$status,'availability'=>$availability]];
 }
 private static function text(mixed$v):string{$v=\trim((string)$v);if($v==='')throw new PilotHttpInfrastructureUnavailable();return$v;}private static function id(mixed$v):?int{$x=\filter_var($v,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);return$x===false?null:$x;}private static function date(mixed$v):string{$v=(string)$v;if(\preg_match('/^(\d{4})-(\d{2})-(\d{2})$/D',$v,$m)!==1||!\checkdate((int)$m[2],(int)$m[3],(int)$m[1]))throw new PilotHttpInfrastructureUnavailable();return$v;}private static function time(mixed$v):string{$v=(string)$v;try{new \DateTimeImmutable($v);}catch(\Throwable){throw new PilotHttpInfrastructureUnavailable();}return$v;}
}
final class ProductionInstallerDirectoryRenderer
{
 public function render(HttpUser$user,array$directory):string
 {
  $all=$directory['installers'];$e=[PilotView::class,'e'];$summary=$directory['summary'];$working=$summary['working'];$assigned=$summary['assigned'];$total=$summary['total'];$filters=$directory['filters'];$last=$directory['lastUpdatedAt']===null?'Список ещё не загружен':(new \DateTimeImmutable($directory['lastUpdatedAt']))->setTimezone(new \DateTimeZone('Europe/Moscow'))->format('d.m.Y H:i');$body='<div class="fm2-page-header"><div><h1>Монтажники</h1><p>Кадровый статус, актуальные закрепления и источник данных</p></div><span class="fm2-result-count">'.$directory['total'].' сотрудников</span></div><section class="fm2-directory-summary"><div><strong>'.$total.'</strong><span>Всего</span></div><div><strong>'.$working.'</strong><span>Работают</span></div><div><strong>'.($total-$working).'</strong><span>Уволены</span></div><p><b>Последний список:</b> '.$e($last).'<br><span>1С ЗУП → Битрикс · обновление каждый час</span></p></section>';
  $select=static function(string$name,string$label,string$value,array$options)use($e):string{$id='installer-'.$name;$buttons='';foreach($options as$optionValue=>$optionLabel)$buttons.='<button class="shlz-select__option" type="button" role="option" aria-selected="'.($value===$optionValue?'true':'false').'" data-value="'.$e($optionValue).'">'.$e($optionLabel).'</button>';return'<div class="shlz-field shlz-field--select shlz-select-root" data-shlz-select><span class="shlz-field__label" id="'.$id.'-label">'.$e($label).'</span><button class="shlz-field__control shlz-select__trigger shlz-select__trigger--selected" type="button" role="combobox" aria-haspopup="listbox" aria-expanded="false" aria-controls="'.$id.'-options" aria-labelledby="'.$id.'-label '.$id.'-value"><span id="'.$id.'-value" data-shlz-select-value>'.$e($options[$value]).'</span><svg class="shlz-select__chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 8.5 12 15.5 19 8.5"/></svg></button><div class="shlz-select__listbox" id="'.$id.'-options" role="listbox" aria-labelledby="'.$id.'-label" hidden>'.$buttons.'</div><input type="hidden" name="'.$e($name).'" value="'.$e($value).'"></div>';};
  $status=$select('status','Статус',$filters['status'],[''=>'Все статусы','employed'=>'Работают','dismissed'=>'Уволены']);$availability=$select('availability','Закрепление',$filters['availability'],[''=>'Любое','assigned'=>'Закреплены','free'=>'Свободны']);$reset=$filters['q']!==''||$filters['status']!==''||$filters['availability']!==''?'<a class="shlz-link fm2-installer-filter-reset" href="/pilot/installers">Сбросить</a>':'';$body.='<form class="fm2-installer-server-filters" method="get" action="/pilot/installers" aria-label="Фильтры справочника монтажников"><label class="shlz-field fm2-installer-search"><span class="shlz-field__label">Поиск</span><span class="shlz-field__control"><input class="shlz-input" type="search" name="q" maxlength="120" value="'.$e($filters['q']).'" placeholder="ФИО или табельный номер"></span></label>'.$status.$availability.'<button class="shlz-button shlz-button--primary" type="submit">Найти</button>'.$reset.'</form>';
  if($all===[])$body.='<section class="shlz-empty-state fm2-empty"><strong>Каталог монтажников пока не загружен</strong></section>';else{$rows='';foreach($all as$x){$active=$x['status']==='employed';$hasAssignment=$x['assignments']!==[];$links='';foreach($x['assignments']as$a)$links.='<a class="shlz-link fm2-assignment-link" href="/pilot/objects/'.$e($a['objectId']).'"><strong>'.$e($a['registrationNumber']).'</strong><span>'.$e($a['address']).'</span></a>';if($links==='')$links='<span class="fm2-assignment-empty">Нет действующих закреплений</span>';$rows.='<tr class="shlz-table__row fm2-installer-row fm2-installer-row--'.($active?'employed':'dismissed').' fm2-installer-row--'.($hasAssignment?'assigned':'free').'"><td class="shlz-table__cell" data-label="Монтажник"><span class="fm2-installer-person"><span class="fm2-person-mark">'.PilotView::initials($x['fullName']).'</span><span><strong>'.$e($x['fullName']).'</strong><small>таб. '.\str_pad((string)$x['tabId'],6,'0',STR_PAD_LEFT).'</small></span></span></td><td class="shlz-table__cell" data-label="Статус"><span class="fm2-employment fm2-employment--'.($active?'active':'dismissed').'">'.($active?'Работает':'Уволен').'</span>'.(!$active&&$x['dismissalEffectiveAt']===null?'<small>Дата увольнения не передана</small>':'').'</td><td class="shlz-table__cell" data-label="Должность">'.$e($x['position']).'</td><td class="shlz-table__cell" data-label="Текущие закрепления"><span class="fm2-assignment-stack">'.$links.'</span></td><td class="shlz-table__cell" data-label="Обновлено"><time>'.$e((new \DateTimeImmutable($x['updatedAt']))->format('d.m.Y H:i')).'</time><small>1С ЗУП → Битрикс</small></td></tr>';}$body.='<section class="fm2-list-surface fm2-installer-directory"><div class="shlz-table-wrap fm2-installer-table-scroll"><table class="shlz-table fm2-installer-table"><caption class="shlz-visually-hidden">Справочник монтажников</caption><thead class="shlz-table__head"><tr class="shlz-table__row"><th class="shlz-table__cell" scope="col">Монтажник</th><th class="shlz-table__cell" scope="col">Статус</th><th class="shlz-table__cell" scope="col">Должность</th><th class="shlz-table__cell" scope="col">Текущие закрепления</th><th class="shlz-table__cell" scope="col">Обновлено</th></tr></thead><tbody>'.$rows.'</tbody></table></div><footer class="fm2-table-footer"><span>Показано '.\count($all).' из '.$directory['total'].'</span>'.PilotView::pagination('/pilot/installers',$directory['page'],$directory['pages'],'Страницы каталога монтажников',\array_filter($filters,static fn($v)=>$v!=='')).'</footer></section>';}
  $body.='<script type="module" src="/pilot/assets/installer-directory.js"></script>';
  return PilotView::document($user,'Монтажники','Монтажники','',$body);
 }
}
